; trades.asm — port-only carrier for the generated in-game trade table
; (pret data/events/trades.asm).
;
; %includes assets/trades.inc (Tier-1 data generated by
; tools/generators/gen_trades.py from pret data/events/trades.asm). The table is
; TradeMons: ten 14-byte rows, each `db give, get, dialogset` followed by an
; 11-byte GB-charmap nickname '@'-padded exactly as RGBDS `dname` pads it.
; DoInGameTradeDialogue (src/engine/events/in_game_trades.asm) indexes it by
; wWhichTrade with a stride of 14 ($e), which is pret's own stride.
;
; WHY THIS FILE EXISTS AND THE TABLE IS NOT IN in_game_trades.asm: pret defines
; TradeMons in data/events/trades.asm and merely INCLUDEs it from the engine
; file. The port mirrors pret paths exactly, so TradeMons' home is this file --
; emitting it into the engine file's translation unit is an `aux_misplaced`
; violation (measured 2026-08-17, and that is exactly how this file came to be).
; InGameTrade_TrainerString is NOT here for the same reason in reverse: pret
; defines that one in engine/events/in_game_trades.asm, so it stays there, via
; the separate assets/trade_trainer_string.inc.
;
; Model: src/data/items/marts.asm — a thin .data carrier for a generated .inc.
; Per the linker rule (docs/assembly.md / link.ld orphan-section trap) embedded
; data lives in .data. This file opens .data and declares the `global`; the .inc
; does neither.
;
; Build: nasm -f coff -I include/ -I . -o trades.o trades.asm

bits 32

%include "gb_memmap.inc"
%include "gb_constants.inc"             ; NAME_LENGTH and the item/species ids
%include "assets/script_constants.inc"  ; species + TRADE_DIALOGSET_* constants

global TradeMons

section .data

%include "assets/trades.inc"
